package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AllowedOriginsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allowed origins of observed source ")
  void test_allowed_origins_v_o_builder() {
    Assertions.assertFalse(AllowedOriginsVO.nullValue().getAllowedOrigins().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AllowedOriginsVO.tryFrom(null).getAllowedOrigins().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", AllowedOriginsVO.from("one").getAllowedOrigins().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AllowedOriginsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AllowedOriginsVO.from("one").toString());
  }
}
